+// Sales from the till. Each dish sold uses one portion of its recipe per
+// quantity; the ingredients are consumed with ref `sale:<ticket>`. A ticket is
+// imported once. An import is all or nothing (docs/DATA.md).
+import { AppError } from "../errors.js";
+import { consume } from "./batches.js";
+import { getItem, onHand } from "./items.js";
+import { getRecipe, scaled } from "./recipes.js";
+
+const round3 = (n) => Math.round(n * 1000) / 1000;
+
+/** True when a ticket has already been imported. */
+export function ticketImported(store, ticket) {
+  return (store.data.sales ?? []).some((s) => s.ticket === ticket);
+}
+
+/**
+ * Records sale lines { row, ticket, soldAt, dishId, qty } and consumes their
+ * ingredients. Lines of tickets already imported are skipped. Throws
+ * not_enough_stock_row (and changes nothing) when an item runs out.
+ */
+export function recordSales(store, lines) {
+  const fresh = lines.filter((l) => !ticketImported(store, l.ticket));
+  const planned = fresh.map((l) => {
+    const dish = (store.data.dishes ?? []).find((d) => d.id === l.dishId);
+    if (!dish) throw new AppError("bad_request", { reason: `row ${l.row}: unknown dish` });
+    return { ...l, uses: scaled(getRecipe(store, dish.recipeId), l.qty) };
+  });
+  // Check every line against what is left after the lines before it.
+  const left = new Map();
+  for (const p of planned) {
+    for (const u of p.uses) {
+      if (!left.has(u.itemId)) left.set(u.itemId, onHand(store, u.itemId));
+      const available = left.get(u.itemId);
+      if (available < u.qty) {
+        const item = getItem(store, u.itemId);
+        throw new AppError("not_enough_stock_row", { row: p.row, item: item.name, available: round3(available), unit: item.unit });
+      }
+      left.set(u.itemId, round3(available - u.qty));
+    }
+  }
+  const before = structuredClone(store.data);
+  try {
+    store.data.sales ??= [];
+    for (const p of planned) {
+      for (const u of p.uses) if (u.qty > 0) consume(store, u.itemId, u.qty, { at: p.soldAt, ref: `sale:${p.ticket}` });
+      store.data.sales.push({ id: store.nextId("sale"), ticket: p.ticket, soldAt: p.soldAt, dishId: p.dishId, qty: p.qty, uses: p.uses });
+    }
+  } catch (e) {
+    store.data = before;
+    throw e;
+  }
+  return {
+    tickets: new Set(planned.map((p) => p.ticket)).size,
+    dishes: planned.reduce((s, p) => s + p.qty, 0),
+  };
+}
